import sys
import urllib.request
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._in_cell = False
        self._cell = ""
        self._row: list[str] = []
        self.rows: list[list[str]] = []

    def handle_starttag(self, tag: str, attrs) -> None:
        if tag == "tr":
            self._row = []
        elif tag == "td":
            self._in_cell = True
            self._cell = ""

    def handle_endtag(self, tag: str) -> None:
        if tag == "td":
            self._in_cell = False
            self._row.append(self._cell.strip())
        elif tag == "tr" and self._row:
            self.rows.append(self._row)

    def handle_data(self, data: str) -> None:
        if self._in_cell:
            self._cell += data

def fetch_table_rows(url: str) -> list[list[str]]:
    with urllib.request.urlopen(url) as response:
        html = response.read().decode("utf-8")

    parser = TableParser()
    parser.feed(html)
    return parser.rows

def parse_entries(rows: list[list[str]]) -> list[tuple[int, int, str]]:
    entries: list[tuple[int, int, str]] = []

    for row in rows:
        if len(row) != 3:
            continue

        x_text, character, y_text = row
        if x_text.lower() == "x-coordinate":
            continue

        try:
            x = int(x_text)
            y = int(y_text)
        except ValueError:
            continue

        entries.append((x, y, character))

    return entries


def build_grid(entries: list[tuple[int, int, str]]) -> list[str]:
    if not entries:
        return []

    max_x = max(x for x, _, _ in entries)
    max_y = max(y for _, y, _ in entries)

    grid = [[" " for _ in range(max_x + 1)] for _ in range(max_y + 1)]
    for x, y, character in entries:
        grid[max_y - y][x] = character

    return ["".join(row) for row in grid]

def decode_secret_message(url: str) -> str:
    rows = fetch_table_rows(url)
    entries = parse_entries(rows)
    return "\n".join(build_grid(entries))

